def top_k_by_score_then_earliest_timestamp(records, k):
    import heapq
    def sort_key(record):
        name, score, timestamp = record
        return (-score, timestamp, name)
    selected = heapq.nsmallest(k, records, key=sort_key)
    return [record[0] for record in selected]

