def shift_time_by_hours(hh, mm, offset_hours):
    total = hh * 60 + mm + offset_hours * 60
    day_delta = 0
    while total < 0:
        total += 1440
        day_delta -= 1
    while total >= 1440:
        total -= 1440
        day_delta += 1
    return (total // 60, total % 60, day_delta)

