def bucket_count_by_width(nums, width, start):
    if not nums:
        return []
    num_buckets = (max(nums) - start) // width + 1
    result = []
    for i in range(num_buckets):
        lo = start + i * width
        hi = lo + width
        count = 0
        for v in nums:
            if lo <= v < hi:
                count += 1
        result.append(count)
    return result

