def middle_characters(s):
    left, right = 0, len(s) - 1
    while right - left > 1:
        left += 1
        right -= 1
    return s[left:right + 1] if s else ""

def mask_email(email):
    local, domain = email.split('@', 1)
    tail = '@' + domain
    if len(local) < 2:
        return local + tail
    if len(local) == 2:
        return local[0] + '*' + tail
    return local[0] + '*' * (len(local) - 2) + local[-1] + tail

def unique_with_counts_sorted(lst):
