def count_repeating_unit_repeats(s):
    n = len(s)
    if n == 0:
        return 0
    fail = [0] * n
    k = 0
    for i in range(1, n):
        while k > 0 and s[i] != s[k]:
            k = fail[k - 1]
        if s[i] == s[k]:
            k += 1
        fail[i] = k
    period = n - fail[-1]
    if n % period == 0:
        return n // period
    return 1

